import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

import axios from 'axios';
import { allUserRoute, host } from '../utils/APIRoutes';
import Contacts from '../components/Contacts';

import '../styles/chat.css';
import Welcome from '../components/Welcome';
import ChatContainer from '../components/ChatContainer';
import { io } from 'socket.io-client';

function Chat() {
  const navigate = useNavigate();
  const socket = useRef();

  const [contacts, setContacts] = useState([]);
  const [currentUser, setCurrentUser] = useState(undefined);
  const [currentChat, setCurrentchat] = useState(undefined);
  const [isLoaded, setIsLoaded] = useState(false);
  // Use Effect 1
  useEffect(() => {
    async function fetchUser() {
      if (!localStorage.getItem('chaxapp-xchat')) {
        navigate('/login');
      } else {
        setCurrentUser(await JSON.parse(localStorage.getItem('chaxapp-xchat')));
        setIsLoaded(true);
      }
    }
    fetchUser();
  }, []);
  useEffect(() => {
    if (currentUser) {
      socket.current = io(host);
      
    }
  }, [currentUser]);
  const handleChatChange = (chat) => {
    setCurrentchat(chat);
  };
  // Use Effect 2
  useEffect(() => {
    async function fetchContacts() {
      if (currentUser) {
        if (currentUser.isProfileImageSet) {
          const data = await axios.get(`${allUserRoute}/${currentUser?._id}`);
          setContacts(data?.data);
        } else {
          navigate('/setProfile');
        }
      }
    }
    fetchContacts();
  }, [currentUser]);
  return (
    <div id="chat_component">
      {/* { <img style={ image } src={ currentUser?.profileImage } alt="" /> } */}
      <Contacts
        contacts={contacts}
        currentUser={currentUser}
        changeChat={handleChatChange}
      />
      {isLoaded &&
        (currentChat === undefined ? (
          <Welcome currentUser={currentUser} />
        ) : (
          <ChatContainer currentChat={currentChat} currentUser={currentUser} />
        ))}
      <div className="chat" style={{ flex: '1 1 60%' }}></div>
    </div>
  );
}

const image = {
  height: '120px',
  width: '120px',
  borderRadius: '50%',
  objectFit: 'cover',
};

export default Chat;
